import sys
from collections import OrderedDict
tokens = sys.stdin.read().split()
if tokens:
    cap = int(tokens[0])
    q_ops = int(tokens[1])
    cache = OrderedDict()
    idx = 2
    for _ in range(q_ops):
        op = tokens[idx]
        if op == 'PUT':
            k, v = int(tokens[idx+1]), int(tokens[idx+2])
            idx += 3
            if k in cache:
                cache.move_to_end(k)
            cache[k] = v
            if len(cache) > cap:
                cache.popitem(last=False)
        elif op == 'GET':
            k = int(tokens[idx+1])
            idx += 2
            if k in cache:
                cache.move_to_end(k)
                print(cache[k])
            else:
                print(-1)
